void awts_browser_navigate(AwtsBrowserState* state) {
  state->navigations++;
  const char* url = state->url;
  if (!strncmp(url, "http://", 7) || !strncmp(url, "https://", 8)) {
    snprintf(state->statusText, sizeof(state->statusText), "network pending: %s", url);
  } else {
    const char* path = url;
    if (!strncmp(url, "file://", 7)) path = url + 7;
    DWORD attrs = GetFileAttributesA(path);
    snprintf(state->statusText, sizeof(state->statusText), "%s: %s", attrs == INVALID_FILE_ATTRIBUTES ? "missing" : "loaded", url);
  }
  printf("navigation[%u]=%s status=%s\n", state->navigations, state->url, state->statusText);
  fflush(stdout);
}

